/****** Object:  UserDefinedFunction [dbo].[CalcularDeuda]    Script Date: 10/09/2026 16:44:46 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE function [dbo].[CalcularDeuda] (@codcli char(4))
returns money
as
begin
declare @vdeuda money
set @vdeuda=(Select Isnull(sum(can_ven*pre_ven),0)
                from tb_detalle_factura D, tb_factura F
                where d.num_fac = f.num_fac and
		     f.cod_cli=@codcli and est_fac='1')
Return @vdeuda
end
GO
/****** Object:  UserDefinedFunction [dbo].[Comision]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create function [dbo].[Comision](@monto money)
returns money
as 
begin
  declare @comi money
  if @monto<500
     set @comi=@monto*0.05
  else
     if @monto<1200
      set @comi=@monto*0.1
    else
      set @comi=@monto*0.15
return @comi
end
GO
/****** Object:  UserDefinedFunction [dbo].[MejorPrecio]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create function [dbo].[MejorPrecio](@codprod char(4))
returns money
as
begin
declare @MejorPrecio money
select top 1 @MejorPrecio=A.Pre_Aba  from Tb_Abastecimiento A
where A.Cod_pro=@codprod
order by A.pre_aba
return @MejorPrecio
end
GO
/****** Object:  UserDefinedFunction [dbo].[MejorProveedor]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE function [dbo].[MejorProveedor](@codprod char(4))
returns varchar(50)
as
begin
declare @nombre varchar(50)
select top 1 @nombre=p.Raz_soc_prv from Tb_Abastecimiento a
inner join Tb_Proveedor p on a.Cod_prv=p.Cod_prv
where a.Cod_pro=@codprod
order by pre_aba
return @nombre
end
GO
