/****** Object:  View [dbo].[vw_VistaClientes]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE   VIEW [dbo].[vw_VistaClientes]
AS
SELECT        C.Cod_cli, C.Raz_soc_cli, C.Ruc_cli, C.Dir_cli, C.Tel_cli, C.Contacto,  C.Fec_reg, DATEDIFF(D, C.Fec_reg, GETDATE()) / 365 AS Antiguedad,C.Est_cli, CASE C.est_cli WHEN 0 THEN 'Inactivo' WHEN 1 THEN 'Activo' END AS Estado,
 C.Tip_cli, CASE C.tip_cli WHEN 1 THEN 'Con opcion a credito' WHEN 2 THEN 'Sin opcion a credito' END AS Tipo,
 U.Departamento, U.Provincia, U.Distrito, C.Usu_Registro, C.Usu_Ult_Mod, C.Fec_Ult_Mod, dbo.CalcularDeuda(C.Cod_cli) AS Deuda
FROM            dbo.Tb_Cliente AS C INNER JOIN
                         dbo.Tb_Ubigeo AS U ON C.Id_Ubigeo = U.Id_Ubigeo
GO
