/****** Object:  View [dbo].[vw_VistaFacturas]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO


CREATE     VIEW [dbo].[vw_VistaFacturas]
AS
SELECT     f.Num_fac, f.Fec_fac, f.Fec_can, C.Cod_cli, C.Raz_soc_cli,C.Ruc_cli ,C.Tel_cli, 
                      U.Departamento ,U.Provincia,U.Distrito ,
                      Convert(decimal(15,2),SUM(d.Can_ven * d.Pre_ven)) AS Total, f.Est_fac, 
                      CASE WHEN f.est_fac = '1' THEN 'Pendiente' WHEN f.est_fac = '2' THEN 'Cancelada' WHEN f.est_fac = '3' THEN 'Anulada' END AS Estado, 
                      f.Cod_ven,V.Nom_ven,V.Ape_ven
FROM         Tb_Factura  F INNER JOIN  Tb_Detalle_Factura D ON f.Num_fac = d.Num_fac 
                      INNER JOIN Tb_Cliente C ON f.Cod_cli = C.Cod_cli
					  INNER JOIN Tb_Vendedor V ON F.Cod_ven=V.Cod_ven
					  INNER JOIN Tb_Ubigeo AS U ON U.Id_ubigeo=C.Id_ubigeo
GROUP BY f.Num_fac, f.Fec_fac, f.Fec_can, C.Cod_cli, C.Raz_soc_cli, C.Ruc_cli ,C.Tel_cli ,
					U.Departamento ,U.Provincia,U.Distrito ,
                    f.Est_fac, f.Cod_ven,V.Nom_ven,V.Ape_ven
GO
