/****** Object:  View [dbo].[vw_VistaOrdenesCompra]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Vista para el SP ListarOrden
CREATE     view [dbo].[vw_VistaOrdenesCompra]
as
SELECT     OC.Num_oco, OC.Fec_oco, OC.Fec_ate, OC.Cod_prv, P.Raz_soc_prv, P.Dir_prv, P.Tel_prv,
		U.Departamento + '-' + U.Provincia + '-' + U.Distrito as Ubicacion,
             OC.Est_oco,         CASE
                          WHEN OC.Est_oco = '1' THEN 'Pendiente' 
                          WHEN OC.Est_oco = '2' THEN 'Atendida' 
                          WHEN OC.Est_oco = '3' THEN 'Anulada' 
                       END AS Estado
FROM         Tb_Orden_Compra  OC INNER JOIN Tb_Proveedor P 
                   ON OC.Cod_prv = P.Cod_prv
				   INNER JOIN Tb_Ubigeo  U on P.Id_Ubigeo = U.Id_Ubigeo 
GO
/****** Object:  UserDefinedFunction [dbo].[FacturasMonto]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create Function [dbo].[FacturasMonto](@Monto1 Money,@Monto2 money)
Returns Table
as
Return Select f.num_fac,fec_fac,fec_can,cod_cli,sum(can_ven*pre_ven) as TotalBruto,
Estado= case when est_fac='1' then 'Pendiente'
                         when est_fac='2' then 'Cancelada'
	                     when est_fac='3' then 'Anulada'
	            end      
from tb_Factura f inner join Tb_Detalle_Factura d
on f.num_fac=d.num_fac  
group by f.num_fac,fec_fac,fec_can,cod_cli,est_fac
having sum(can_ven*pre_ven) between  @monto1 and @monto2
GO
