/****** Object:  View [dbo].[vw_VistaVendedores]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE view [dbo].[vw_VistaVendedores]
as
SELECT V1.Cod_ven
      ,V1.Nom_ven
      ,V1.Ape_ven
      ,V1.Sue_ven
      ,V1.Fec_ing
      ,V1.Tip_ven
	  , Case V1.Tip_ven 
	      when 1 then 'Supervisor de ventas'
		  when 2 then 'Ejecutivo de ventas'
		end as Tipo
	  , V1.Dni_ven 
      ,V1.Email_ven
      ,V1.Cod_Supervisor
	  ,V2.Nom_ven + ' ' + V2.Ape_ven as NomSupervisor
	  ,V1.Fec_Registro
      ,V1.Usu_Registro
      ,V1.Fec_Ult_Mod
      ,V1.Usu_Ult_Mod
      ,V1.Est_ven
	  ,case V1.est_ven
	   when  0 then 'Inactivo'
	   When 1 then 'Activo'
	end  as Estado
  FROM Tb_Vendedor V1 inner join Tb_Vendedor V2 on V1.Cod_Supervisor =V2.Cod_ven 
GO
