/****** Object:  View [dbo].[vw_VistaProductos]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   View  [dbo].[vw_VistaProductos]
as
SELECT P.Cod_pro
      ,P.Des_pro
      ,P.Pre_pro
      ,P.Stk_act
      ,P.Stk_min
      ,P.Id_UM
	  ,U.Des_UM 
      ,P.Id_Cat
	  ,C.Des_Cat 
      ,P.Importado
	  ,case P.Importado 
	       when 1 then 'Importado'
		   when 0 then 'Nacional'
	  end as Origen
      ,P.Fec_Registro
      ,P.Usu_Registro
      ,P.Fec_Ult_Mod
      ,P.Usu_Ult_Mod
      ,P.Est_pro
	  ,case P.Est_pro 
	       when 1 then 'Activo'
		   when 0 then 'Inactivo'
	  end as Estado
	  ,dbo.MejorPrecio (P.Cod_pro ) as MejorPrecioAbast
	  FROM Tb_Producto P inner join Tb_UnidadMedida U on P.id_UM = U.Id_UM
	                     inner join Tb_Categoria C on P.id_cat=C.id_cat
GO
/****** Object:  View [dbo].[vw_VistaProveedores]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE VIEW [dbo].[vw_VistaProveedores]
as
SELECT V.Cod_prv
      ,V.Raz_soc_prv
      ,V.Dir_prv
      ,isnull(V.Tel_prv,'-') as Tel_prv
      ,V.Ruc_Prv
      ,isnull(V.Rep_ven,'-') as Rep_ven
      ,V.Id_Ubigeo
	  ,U.Departamento
		,U.Provincia
		,U.Distrito 
      ,V.Fec_Registro
      ,V.Usu_Registro
      ,V.Fec_Ult_Mod
      ,V.Usu_Ult_Mod
      ,V.Est_prv
	  , case V.est_prv
	       when 1 then 'Activo'
		   when 0 then 'Inactivo'
		end as Estado
		
  FROM Tb_Proveedor V inner join Tb_Ubigeo U on V.Id_Ubigeo=U.Id_Ubigeo
GO
/****** Object:  View [dbo].[vw_DemoPivot]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create view [dbo].[vw_DemoPivot]
as
SELECT Raz_soc_cli ,   month(fec_fac) AS Mes,   SUM(Total) AS Monto 
FROM vw_vistaFacturas
WHERE year(fec_fac) = 2005 
GROUP BY Raz_soc_cli,month(fec_fac) 
GO
/****** Object:  View [dbo].[vw_VistaClientesVentas]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create view [dbo].[vw_VistaClientesVentas]
as
Select C.cod_cli,C.Raz_soc_Cli,C.Ruc_cli,C.dir_cli ,C.Tel_cli,C.Contacto ,C.Est_cli ,C.Fec_Reg,DATEDIFF(D,C.fec_reg,GETDATE()) / 365 as Antiguedad ,
	case C.est_cli 
	   when  0 then 'Inactivo'
	   When 1 then 'Activo'
	end  as Estado,
	C.Departamento ,C.Provincia ,C.Distrito,Convert(Money,Isnull(SUM(Total),0)) as TotalFacturado
from VW_VistaClientes  C left outer join Vw_VistaFacturas F on C.Cod_cli =F.Cod_cli and F.Est_fac <>3
--where F.Est_fac <>3
group by C.cod_cli,C.Raz_soc_Cli,C.Ruc_cli,C.dir_cli ,C.Tel_cli,C.Contacto ,C.Est_cli ,C.Fec_Reg,
			C.Departamento ,C.Provincia ,C.Distrito
GO
