CREATE   PROCEDURE [dbo].[usp_ActualizarCategoria]
@Id_Cat int,
@Des_Cat varchar(50),
@Foto_Cat image
AS
update Tb_Categoria set Des_Cat=@Des_Cat,Foto_Cat =@Foto_Cat
where Id_Cat=@Id_Cat
GO
