CREATE PROCEDURE [dbo].[usp_ActualizarProducto]
@vcod char(4),
@vdes varchar(50),
@vpre money,
@vstka integer,
@vstkm integer,
@vId_UM int,
@vId_Cat int,
@vimp int,
@vUsu_ult_mod varchar(20),
@vest_pro int 
AS
update tb_producto set des_pro=@vdes,
pre_pro=@vpre,stk_act=@vstka,stk_min=@vstkm,
Id_UM=@vID_UM ,Id_Cat=@vId_Cat,importado=@vimp,Usu_Ult_Mod=@vUsu_ult_mod ,Fec_Ult_Mod = GETDATE(),
Est_pro =@vest_pro
where cod_pro=@vcod
GO
