CREATE PROCEDURE [dbo].[usp_ActualizarProveedor]
@vcod char(4),
@vraz varchar(50),
@vdir varchar(50),
@vtel varchar(10),
@vruc char(11),
@vrep varchar(30),
@vId_Ubigeo char(6),
@vUsu_Ult_Mod varchar(20),
@vest_prv int
AS
Update tb_proveedor set raz_soc_prv=@vraz,dir_prv=@vdir,
tel_prv=@vtel,ruc_prv=@vruc,rep_ven=@vrep,id_ubigeo=@vId_ubigeo,
Usu_ult_mod =@vUsu_Ult_Mod , Fec_Ult_Mod=getdate(),est_prv=@vest_prv
where cod_prv=@vcod
GO
