CREATE PROCEDURE [dbo].[usp_ActualizarVendedor]
@vcod char(3),
@vnom varchar(25),
@vape varchar(25),
@vsue money,
@vfec smalldatetime,
@vtip int,
@vDNI char(8),
@vEmail varchar(50),
@vcodSup char(3),
@vUsu_ult_mod varchar(20),
@vest_ven int
AS
Update tb_vendedor set nom_ven=@vnom,ape_ven=@vape,
sue_ven=@vsue,fec_ing=@vfec,tip_ven=@vtip,DNI_ven= @vDNI,Email_ven =@vEmail ,Cod_Supervisor =@vcodSup ,
Usu_Ult_Mod =@vUsu_ult_mod ,
Fec_Ult_Mod = GETDATE(),Est_ven =@vest_ven 
where cod_ven=@vcod
GO
