CREATE PROCEDURE [dbo].[usp_CancelarFactura]
@vnumfac char(6),
@vfeccan smalldatetime,
@Usu_ult_mod varchar(20)
AS
Update tb_factura set est_fac='2',fec_can=@vfeccan,Usu_Ult_Mod =@Usu_ult_mod , Fec_Ult_Mod =GETDATE()
