GO
CREATE PROCEDURE [dbo].[usp_Consultar_Detalle_Factura]  
@vnum_fac char(6)
AS
select num_fac as NumFactura,D.cod_pro as Codigo,des_pro as Descripcion ,
pre_ven as Precio,can_ven as Cantidad ,(pre_ven*can_ven) as SubTotal
from Tb_Detalle_Factura D inner join Tb_Producto P on D.Cod_pro =P.Cod_pro  
where Num_fac  =@vnum_fac
GO
