      ,[Departamento]
      ,[Provincia]
      ,[Distrito]
      ,[Usu_Registro]
      ,[Usu_Ult_Mod]
      ,[Fec_Ult_Mod]
      ,[Deuda]
  FROM [dbo].[vw_VistaClientes]
  where cod_cli=@vcod
