CREATE  PROCEDURE [dbo].[usp_InsertarClienteXML]
@DOCUMENTOXML TEXT
AS 
/* SE INSERTARAN LOS CLIENTES ESPECIFICADOS EN
   EL PARAMETRO DEL DOC XML */
	SET NOCOUNT OFF
	DECLARE @IDDOCXML INT
	/* SE CREA UN DOCUMENTO XML TEMPORAL */
	EXECUTE SP_XML_PREPAREDOCUMENT @IDDOCXML OUTPUT, @DOCUMENTOXML
	/* SE INSERTA LOS REGISTROS EN MISCLIENTES */
	INSERT INTO TB_NUEVOSCLIENTES (
                    COD_CLI, RAZ_SOC_CLI,DIR_CLI,TEL_CLI)
	SELECT COD_CLI,RAZ_SOC_CLI,DIR_CLI,TEL_CLI
	FROM 
	OPENXML (@IDDOCXML, '/ROOT/MisClientes')
	 WITH ( COD_CLI 	CHAR(4)	'@Cod_cli', 
		          RAZ_SOC_CLI VARCHAR(30)  '@Raz_soc_cli' ,
        	      DIR_CLI VARCHAR (30)  '@Dir_cli',
		         TEL_CLI CHAR (8) '@Tel_cli') 
	/* SE ELIMINA EL DOCUMENTO XML TEMPORAL */
	EXECUTE SP_XML_REMOVEDOCUMENT @IDDOCXML
	RETURN  @@ERROR
GO
