CREATE PROCEDURE [dbo].[usp_InsertarProducto]
@vdes varchar(40),
@vpre money,
@vstka integer,
@vstkm integer,
@vId_UM integer,
@vId_Cat integer,
@vimp integer,
@vUsu_Registro varchar(20),
@vEst_pro integer
AS
declare @vcod char(4) 
declare @vcont int
set @vcont=(Select count(*) from tb_producto)
if @vcont=0 
       set @vcod ='P001'
else
--Se ´puede usar tambien substring para tomar desde la segunda
--posicion tres caracteres
Set @vcod=(select 'P' + right(max(substring(cod_pro,2,3)+1001),3) 
                      from Tb_Producto)
insert into tb_producto values 
(@vcod,@vdes,@vpre,@vstka,@vstkm ,@vId_UM ,@vId_Cat ,@vimp,GETDATE(),@vUsu_Registro ,Null,Null,@vEst_pro ) 
GO
