SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO




CREATE PROCEDURE [dbo].[usp_ListarDistritoPag]
@FILTRO VARCHAR(100),
@NUMREG	INT OUTPUT,
@NUMPAG	INT

AS
DECLARE @PAGESIZE INT
	SET @PAGESIZE=5

IF @FILTRO='' 
	BEGIN
		SELECT TOP 5
			COD_DIS,
			NOM_DIS,
			COD_VEN
		FROM TB_DISTRITO ORDER BY NOM_DIS
		------------------------------------------------------------------------------
		DECLARE @CONTADOR INT		
		SET @CONTADOR=(SELECT COUNT (COD_DIS) FROM TB_DISTRITO)
		IF  @CONTADOR>=5
			SET @NUMREG=5
		ELSE
			SET @NUMREG=@CONTADOR
		SET @NUMPAG=1
		-------------------------------------------------------------------------------
	END
ELSE
	BEGIN
	SELECT TOP 5
			COD_DIS,
			NOM_DIS,
			COD_VEN FROM
			(	SELECT  
				COD_DIS,
				NOM_DIS,
				COD_VEN,
				ROW_NUMBER() OVER (ORDER BY COD_DIS DESC) AS RowNumber 
				FROM  TB_DISTRITO
				WHERE NOM_DIS LIKE '%' + @FILTRO + '%'
				
	) AS PAGINA WHERE RowNumber BETWEEN @PageSize * @NUMPAG + 1 AND @PageSize * (@NUMPAG + 1)
	ORDER BY NOM_DIS

	--SE OBTIENE EL NUMERO DE PAGINAS
	------------------------------------------------------------------------------
	SET @NUMREG=
		(	SELECT  COUNT(COD_DIS)
			FROM  TB_DISTRITO
			WHERE NOM_DIS LIKE '%' + @FILTRO + '%' )
	END




GO
