/****** Object:  StoredProcedure [dbo].[usp_ListarFacturas_Paginacion]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_ListarFacturas_Paginacion]
@Cod_cli varchar(4),
@Cod_ven varchar(3),
@Estado varchar(10),
@NumPag int
AS
DECLARE @NUMREG INT
DECLARE @PAGESIZE INT
SET @PAGESIZE=50 --Tamaño de pagina

IF @Cod_cli='' AND @Cod_ven='' AND  @Estado='' 
    BEGIN
			-- Si los valores de los parametros son cadenas en blanco , se obtienen los primeros 50 registros
	           SELECT top 50  Num_fac,Fec_fac,Fec_can,Cod_cli,Raz_soc_cli,Ruc_cli,Departamento,Provincia ,Distrito,
			   Cod_ven, Ape_ven ,Nom_ven ,Total, Estado 
               from vw_VistaFacturas 
			   ORDER BY Num_fac DESC
			
	END
ELSE
   BEGIN
	-- En caso contrario se analizan los parametros pasados
             IF @Cod_cli=''
			         SET @Cod_cli='%'

			 IF @Cod_ven=''
			         SET @Cod_ven='%'

			 IF @Estado=''
			         SET @Estado='%'

              
               SELECT top 50  Num_fac,Fec_fac,Fec_can,Cod_cli,Raz_soc_cli,Ruc_cli,Departamento,Provincia ,Distrito,
			   Cod_ven, Ape_ven ,Nom_ven ,Total, Estado 
               from 			  
		 
		 ( SELECT  Num_fac,Fec_fac,Fec_can,Cod_cli,Raz_soc_cli,Ruc_cli,Departamento,Provincia ,Distrito,
			   Cod_ven, Ape_ven ,Nom_ven ,Total, Estado ,
				ROW_NUMBER() OVER (ORDER BY Num_fac DESC) AS NumOrden 
				from vw_VistaFacturas
				where 
				     Cod_cli like '%' + @Cod_cli + '%'
				 and Cod_ven like '%' + @Cod_ven + '%'
			     and Estado like  '%' + @Estado + '%'
				
			) AS CONSULTAPAGINADA 
			WHERE NumOrden BETWEEN @PageSize * @NUMPAG + 1 AND @PageSize * (@NUMPAG + 1)
	            ORDER BY Num_fac desc 
END

GO
