/****** Object:  StoredProcedure [dbo].[usp_NumPag_ListarFacturas_Paginacion]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[usp_NumPag_ListarFacturas_Paginacion]
@Cod_cli varchar(4),
@Cod_ven varchar(3),
@Estado varchar(10),
@NUMREG	INT OUTPUT
AS
-- OBTIENE EL NUMERO DE PAGINAS DEL usp_ListarFacturas_Paginacion
	IF @Cod_cli='' AND @Cod_ven='' AND  @Estado='' 
	   -- Si no hay valores significativos en los parametros devuelve 50 o si la cantidad de registeos
	   -- que existan 
		BEGIN
		DECLARE @CONTADOR INT		
		SET @CONTADOR=(SELECT COUNT (*)   from vw_VistaFacturas)
		IF  @CONTADOR>=50
			SET @NUMREG=50
		ELSE
			SET @NUMREG=@CONTADOR
		END
	ELSE
		BEGIN
		  	-- En caso contrario se analizan los parametros pasados y se obtiene el numero de registros que cumplen
			-- las condiciones de filtrado
             IF @Cod_cli=''
			         SET @Cod_cli='%'

			 IF @Cod_ven=''
			         SET @Cod_ven='%'

			 IF @Estado=''
			         SET @Estado='%'

			SET @NUMREG=
			(	SELECT COUNT (*)  from vw_VistaFacturas
				where 
				     Cod_cli like '%' + @Cod_cli + '%'
				 and Cod_ven like '%' + @Cod_ven + '%'
			     and Estado like  '%' + @Estado + '%')
		END

GO
