Create Procedure [dbo].[usp_PaginacionClientes]
@desde int,
@hasta int
as 
SELECT Nro_Orden
	   ,[Cod_cli]
      ,[Raz_soc_cli]
      ,[Ruc_cli]
      ,[Dir_cli]
      ,[Tel_cli]
      ,[Contacto]
      ,[Fec_reg]
      ,[Antiguedad]
      ,[Est_cli]
      ,[Estado]
      ,[Tip_cli]
      ,[Tipo]
      ,[Departamento]
      ,[Provincia]
      ,[Distrito]
      ,[Usu_Registro]
      ,[Usu_Ult_Mod]
      ,[Fec_Ult_Mod]
      ,[Deuda]
FROM 
(SELECT row_number() over (order by Raz_soc_cli) as Nro_orden
       ,[Cod_cli]
      ,[Raz_soc_cli]
      ,[Ruc_cli]
      ,[Dir_cli]
      ,[Tel_cli]
      ,[Contacto]
      ,[Fec_reg]
      ,[Antiguedad]
      ,[Est_cli]
      ,[Estado]
      ,[Tip_cli]
      ,[Tipo]
      ,[Departamento]
      ,[Provincia]
      ,[Distrito]
      ,[Usu_Registro]
      ,[Usu_Ult_Mod]
      ,[Fec_Ult_Mod]
      ,[Deuda]
                 FROM vw_VistaClientes) as Tabla
WHERE Nro_orden  between @desde  and @hasta
GO
