GO
SET QUOTED_IDENTIFIER ON
GO
Create Procedure [dbo].[usp_RankingProductosAño]
@año int
as
Select Des_pro, Convert(Money,(isnull(SUM(can_ven*pre_ven),0))) as TotalVentas
from Tb_Producto P inner join Tb_Detalle_Factura DF on P.Cod_pro =DF.Cod_pro 
                   inner join Tb_Factura F on F.Num_fac =DF.Num_fac 
where F.Est_fac <>3 and YEAR(fec_fac)=@año
group by Des_pro
order by TotalVentas desc
GO
/****** Object:  StoredProcedure [dbo].[usp_RegistrarOcompra]    Script Date: 10/09/2026 16:44:47 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[usp_RegistrarOcompra] 
   	@vfecoco smalldatetime,
	@vcodprv char(4),
	@vfecate smalldatetime,
	@vestoco int,
	@vUsu_registro varchar(20),
    @vnumoco char(6) output,
    @detalles MisdetallesOC readonly -- parametro tipo tabla
AS
-- INICIAMOS TRANSACCION
Begin Transaction
	Begin Try -- Iniciamos bloque Try en SQL
		declare @vcont int
		set @vcont=(Select count(*) from tb_Orden_Compra)
		if @vcont=0 
			set @vnumoco ='OC0001'
		else
			--Se genera el numero de Orden de Compra
			Set @vnumoco=(select 'OC' + right(max(right(num_oco,4)+10001),4) 
                              from Tb_Orden_Compra)
			--1ro. Se inserta la cabecera
		INSERT INTO Tb_Orden_Compra values 
                             (@vnumoco,@vfecoco,@vcodprv,@vfecate,@vestoco,GETDATE(),@vUsu_registro ,null,null)
		-- 2do.  Se inserta el detalle
		INSERT INTO Tb_Detalle_Compra
		SELECT @vnumoco as num_oc, cod,can
		FROM @detalles 
		-- 3ro. Si todo esta OK, se confirma la transaccion
		Commit Transaction
	End Try
	Begin Catch
		-- Si algo fallo se cancela la transaccion
		Print @@error
        Rollback Transaction
	End Catch
GO
